// === ESTRUCTURA DEL PATRÓN MEDIATOR ===

// 1. Interfaz Mediator (el contrato)
interface ChatMediator {
  sendMessage(message: string, sender: User): void;
  addUser(user: User): void;
}

// 2. Mediator Concreto (la coordinación)
class ChatRoom implements ChatMediator {
  private users: User[] = [];

  addUser(user: User) {
    this.users.push(user);
    user.setMediator(this);
  }

  sendMessage(message: string, sender: User) {
    this.users.forEach(user => {
      if (user !== sender) {
        user.receive(message, sender.name);
      }
    });
  }
}

// 3. Componentes (colleagues)
class User {
  private mediator: ChatMediator | null = null;
  constructor(public name: string) {}

  setMediator(mediator: ChatMediator) {
    this.mediator = mediator;
  }

  send(message: string) {
    this.mediator?.sendMessage(message, this);
  }

  receive(message: string, from: string) {
    console.log(`${from}: ${message}`);
  }
}

// Uso:
const room = new ChatRoom();
const alice = new User('Alice');
const bob = new User('Bob');
room.addUser(alice);
room.addUser(bob);
alice.send('Hola Bob!'); // Bob recibe: 'Alice: Hola Bob!'

