// 1. Interfaz común
interface Mediator {
  notify(sender: User, event: string): void;
}

// 2. Mediator concreto coordina
class ChatMediator implements Mediator {
  private users: User[] = [];

  addUser(user: User) {
    this.users.push(user);
    user.setMediator(this);
  }

  notify(sender: User, event: string) {
    this.users.forEach(user => {
      if (user !== sender) user.handle(event);
    });
  }
}

// 3. Los usuarios solo conocen al mediador
class User {
  private mediator: Mediator | null = null;
  setMediator(m: Mediator) { this.mediator = m; }
  send(event: string) { this.mediator?.notify(this, event); }
  handle(event: string) { console.log(event); }
}

